long long a[1005][1005];
long long pref[1005][1005];

void solve()
{
    long long n, q;
    cin >> n >> q;
    for(int i = 0; i <= 1001; i++)
    {
        for(int j = 0; j <= 1001; j++)
        {
            a[i][j] = pref[i][j] = 0;
        }
    }
    for(int i = 0; i < n; i++)
    {
        long long h, w;
        cin >> h >> w;
        a[h][w]+=h*w;
    }
    for(int i = 1; i <= 1000; i++)
    {
        for(int j = 1; j <= 1000; j++)
        {
            pref[i][j] = pref[i-1][j]+pref[i][j-1]-pref[i-1][j-1]+a[i][j];
        }
    }
    for(int i = 0; i < q; i++)
    {
        long long hs, ws, hb, wb;
        cin >> hs >> ws >> hb >> wb;
        cout << pref[hb-1][wb-1]-pref[hb-1][ws]-pref[hs][wb-1]+pref[hs][ws] << endl;
    }
}

int main() {
    int t = 1;
    cin >> t;
    while(t--)
    {
        solve();
    }
}

#include <bits/stdc++.h>

using namespace std;

const int MAX = 200007;
const int MOD = 1000000007;

const int dx[3] = {-1, 0, 1}, dy[3] = {-1, 0, 1};

void solve() {
	int n, m;
	cin >> n >> m;
	char g[n][m];
	int id[n][m];
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			cin >> g[i][j];
			id[i][j] = 0;
		}
	}
	int curr = 1;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			if (g[i][j] == '*') {
				vector<pair<int, int>> adjh, adjv;
				if (i > 0 && g[i - 1][j] == '*') {
					adjh.emplace_back(i - 1, j);
				}
				if (i < n - 1 && g[i + 1][j] == '*') {
					adjh.emplace_back(i + 1, j);
				}
				if (j > 0 && g[i][j - 1] == '*') {
					adjv.emplace_back(i, j - 1);
				}
				if (j < m - 1 && g[i][j + 1] == '*') {
					adjv.emplace_back(i, j + 1);
				}
				if (adjh.size() == 1 && adjv.size() == 1) {
					if (id[i][j] == 0) {id[i][j] = curr;}
					else {cout << "NO\n"; return;}
					if (id[adjh[0].first][adjh[0].second] == 0) {id[adjh[0].first][adjh[0].second] = curr;}
					else {cout << "NO\n"; return;}
					if (id[adjv[0].first][adjv[0].second] == 0) {id[adjv[0].first][adjv[0].second] = curr;}
					else {cout << "NO\n"; return;}
					curr++;
				}
				else if (adjh.size() > 1 || adjv.size() > 1) {
					cout << "NO\n"; return;
				}
			}
		}
	}
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			if (g[i][j] == '*') {
				if (id[i][j] == 0) {cout << "NO\n"; return;}
				else {
					for (int x = 0; x < 3; x++) {
						for (int y = 0; y < 3; y++) {
							if (0 <= i + dx[x] && i + dx[x] < n) {
								if (0 <= j + dy[y] && j + dy[y] < m) {
									if (id[i + dx[x]][j + dy[y]] != id[i][j] && id[i + dx[x]][j + dy[y]] != 0) {
										cout << "NO\n"; return;
									}
								}
							}
						}
					}
				}
			}
		}
	}
	cout << "YES\n";
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int tt; cin >> tt; for (int i = 1; i <= tt; i++) {solve();}
	// solve();
}

#include <bits/stdc++.h>

using namespace std;

void solve()
{
    int n;
    cin >> n;
    int case1 = 0;
    int case2 = 0;
    for(int i = 0; i < n-2; i++)
    {
        case1^=i;
        case2^=(i+1);
    }
    long long addLast = ((long long)1<<31)-1;
    if(case1 != 0)
    {
        for(int i = 0; i < n-2; i++)
        {
            cout << i << " ";
        }
        case1^=addLast;
        cout << addLast << " " << case1 << endl;
    }
    else
    {
        for(int i = 1; i <= n-2; i++)
        {
            cout << i << " ";
        }
        case2^=addLast;
        cout << addLast << " " << case2 << endl;
    }
}

int main()
{
    int t = 1;
    cin >> t;
    while(t--)
    {
        solve();
    }
}
